// ===== 2. プレイヤー + スイング物理 =====
const SPAWN = lonLatToEcef(34.9965, 135.7585, 130); // 四条烏丸上空
const P = { pos:SPAWN.clone(), vel:new THREE.Vector3(), attached:false, anchor:new THREE.Vector3(), ropeLen:0 };
const GRAV=22, MAX_ROPE=260, MIN_H=2;
const ray = new THREE.Raycaster(); ray.far=800;
if('firstHitOnly' in ray) ray.firstHitOnly = true;

const playerMesh = new THREE.Mesh(new THREE.SphereGeometry(1.4,20,20), new THREE.MeshStandardMaterial({color:0x00ff88, emissive:0x003311}));
scene.add(playerMesh);
const ropeLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints([P.pos,P.pos]), new THREE.LineBasicMaterial({color:0xffffff}));
ropeLine.visible=false; scene.add(ropeLine);
const anchorBall = new THREE.Mesh(new THREE.SphereGeometry(1.8,14,14), new THREE.MeshBasicMaterial({color:0xff3344}));
anchorBall.visible=false; scene.add(anchorBall);

// 視点 yaw/pitch (ポインターロックで操作)
let yaw=Math.PI, pitch=-0.15;
const keys={};
addEventListener('keydown',e=>{keys[e.code]=true; if(e.code==='Space'){detach();e.preventDefault();} if(e.code==='KeyR')respawn();});
addEventListener('keyup',e=>keys[e.code]=false);
addEventListener('contextmenu',e=>e.preventDefault());

function viewDir(){
  const east=new THREE.Vector3().crossVectors(new THREE.Vector3(0,0,1),UP).normalize();
  const north=new THREE.Vector3().crossVectors(UP,east).normalize();
  return north.clone().multiplyScalar(Math.cos(pitch)*Math.cos(yaw))
    .addScaledVector(east, Math.cos(pitch)*Math.sin(yaw))
    .addScaledVector(UP, Math.sin(pitch)).normalize();
}
function shoot(){
  ray.setFromCamera(new THREE.Vector2(0,0), camera);
  const hits = ray.intersectObject(tiles.group, true);
  const h = hits[0];
  if(!h) return;
  const upDist = h.point.clone().sub(P.pos).dot(UP);
  if(h.distance < MAX_ROPE && upDist > 4){
    P.attached=true; P.anchor.copy(h.point); P.ropeLen=h.distance;
    anchorBall.visible=true; anchorBall.position.copy(h.point);
    ropeLine.visible=true;
  }
}
function detach(boost=1.18){
  if(!P.attached) return;
  P.attached=false; anchorBall.visible=false; ropeLine.visible=false;
  P.vel.multiplyScalar(boost).addScaledVector(UP,5);
}
function respawn(){ P.pos.copy(SPAWN); P.vel.set(0,0,0); detach(); P.attached=false; ropeLine.visible=false; anchorBall.visible=false; }
addEventListener('pointerdown',e=>{ if((!started&&!window.__started)||e.target.closest('#card'))return; if(e.button===2)detach(); else if(e.button===0)shoot(); });
addEventListener('mousemove',e=>{
  if(!document.pointerLockElement) return;
  yaw -= e.movementX*0.0022; pitch -= e.movementY*0.0022;
  pitch = THREE.MathUtils.clamp(pitch,-1.2,1.2);
});

function stepPlayer(dt){
  const fwd = viewDir();
  P.vel.addScaledVector(UP,-GRAV*dt);
  P.vel.multiplyScalar(Math.max(0,1-0.10*dt));
  const right=new THREE.Vector3().crossVectors(fwd,UP).normalize();
  if(P.attached && keys['KeyW']) P.ropeLen=Math.max(12,P.ropeLen-16*dt);
  if(P.attached && keys['KeyS']) P.ropeLen=Math.min(MAX_ROPE,P.ropeLen+16*dt);
  if(keys['KeyW']&&!P.attached) P.vel.addScaledVector(fwd,26*dt);
  if(keys['KeyS']&&!P.attached) P.vel.addScaledVector(fwd,-10*dt);
  if(keys['KeyA']) P.vel.addScaledVector(right,-22*dt);
  if(keys['KeyD']) P.vel.addScaledVector(right,22*dt);
  P.pos.addScaledVector(P.vel,dt);

  if(P.attached){
    const d=P.pos.clone().sub(P.anchor); const dist=d.length();
    if(dist>P.ropeLen){
      const n=d.divideScalar(dist||1);
      P.pos.copy(P.anchor).addScaledVector(n,P.ropeLen);
      const vOut=P.vel.dot(n);
      if(vOut>0) P.vel.addScaledVector(n,-vOut);
      P.vel.addScaledVector(fwd,7*dt); // ポンプ加速
    }
    if(P.pos.distanceTo(P.anchor)>MAX_ROPE*1.2) detach(1);
  }
  const h=P.pos.clone().sub(ORIGIN).dot(UP);
  if(h<MIN_H){ P.pos.addScaledVector(UP,MIN_H-h);
    const vUp=P.vel.dot(UP); if(vUp<0)P.vel.addScaledVector(UP,-vUp*1.6); P.vel.multiplyScalar(0.96); }
  playerMesh.position.copy(P.pos);
  if(P.attached) ropeLine.geometry.setFromPoints([P.pos,P.anchor]);

  // カメラ追従 + FOV演出
  const speed=P.vel.length();
  const want=P.pos.clone().addScaledVector(fwd,-10).addScaledVector(UP,4);
  camera.position.lerp(want,1-Math.pow(0.0005,dt));
  camera.lookAt(P.pos.clone().addScaledVector(fwd,12).addScaledVector(P.vel,0.25));
  const tFov=THREE.MathUtils.clamp(62+speed*0.55,62,93);
  camera.fov+=(tFov-camera.fov)*Math.min(1,dt*4); camera.updateProjectionMatrix();
  // HUD + 照準色
  const kmh=Math.round(speed*3.6);
  document.getElementById('stat').textContent=`速度 ${kmh}km/h 高度 ${Math.round(h)}m ${P.attached?('ロープ '+Math.round(P.ropeLen)+'m'):'送電線なし — ビルを狙ってクリック'}`;
  document.getElementById('cross').className = P.attached?'ok':'';
}

// 照準アシスト: 中央にビルがあれば照準を赤く
let started=false;
function hideStartHint(){}
document.getElementById('go').onclick=()=>{
  document.getElementById('start').style.display='none';
  started=true; window.__started=true; renderer.domElement.requestPointerLock?.();
  camera.position.copy(P.pos.clone().addScaledVector(viewDir(),-10).addScaledVector(UP,4));
};
renderer.domElement.addEventListener('click',()=>{ if(started) renderer.domElement.requestPointerLock?.(); });

const clock=new THREE.Clock();
(function loop(){
  requestAnimationFrame(loop);
  const dt=Math.min(clock.getDelta(),0.05);
  tiles.setCamera(camera); tiles.setResolutionFromRenderer(camera,renderer);
  camera.updateMatrixWorld(); tiles.update();
  if(started||window.__started) stepPlayer(dt);
  else { // 開始前は京都駅をゆっくり周回
    const t=performance.now()*0.0001;
    camera.position.copy(lonLatToEcef(34.99+t*0.002%0.02,135.758,300));
    camera.lookAt(lonLatToEcef(34.994,135.758,50));
  }
  // 照準チェック (1秒に5回だけ)
  renderer.render(scene,camera);
})();
</script>
