input.newString:
function tryAttach(h){
  if(!h) return false;
  const upDist = h.point.clone().sub(P.pos).dot(UP);
  if(h.distance < MAX_ROPE && upDist > 3){
    P.attached=true; P.anchor.copy(h.point); P.ropeLen=Math.min(h.distance,MAX_ROPE);
    anchorBall.visible=true; anchorBall.position.copy(h.point);
    ropeLine.visible=true;
    return true;
  }
  return false;
}
function nearestHit(){
  let h = null;
  for(const t of tilesList){
    const hits = ray.intersectObject(t.group, true);
    if(hits.length && (!h || hits[0].distance < h.distance)) h = hits[0];
  }
  if(!h){
    // フォールバック街や地面にも引っ掛けられるように全シーンで再試行
    const hits2 = ray.intersectObjects(scene.children.filter(o=>o!==ropeLine&&o!==anchorBall&&o!==hero), true);
    if(hits2.length) h = hits2[0];
  }
  return h;
}
function shoot(){
  ray.setFromCamera(new THREE.Vector2(0,0), camera);
  tryAttach(nearestHit());
}
function autoShoot(){
  _t1.copy(P.pos).addScaledVector(fwdCache,60).addScaledVector(UP,30);
  ray.set(P.pos,_t1.sub(P.pos).normalize());
  tryAttach(nearestHit());
}

