const wardUrls = new URLSearchParams(location.search).has('ward') ? [WARD_URLS[0]] : WARD_URLS;
let tilesReady = false, fallbackDone = false, tileCount = 0;
function tpMsg(s){ const el=document.getElementById('tp'); if(el) el.textContent=s; }
// PLATEAU 2025 LOD2はDraco圧縮 → デコーダを登録
const dracoLoader = new DRACOLoader();
dracoLoader.setDecoderPath('./libs/draco/');
const gltfLoader = new GLTFLoader();
gltfLoader.setDRACOLoader(dracoLoader);
const tilesList = wardUrls.map(u=>{
  const t = new TilesRenderer(u);
  t.manager.addHandler(/\.gltf$/, gltfLoader);
  t.setCamera(camera);
  t.setResolutionFromRenderer(camera, renderer);
  scene.add(t.group);
  t.addEventListener('load-model', ()=>{ tilesReady = true; tileCount++; tpMsg(`PLATEAU: 建物 ${tileCount}件取得`); });
  return t;
});
function ensureFallback(msg){
  if(fallbackDone || tilesReady) return;
  fallbackDone = true; buildFallbackCity();
  document.getElementById('stat').textContent = msg || '(フォールバック街でプレイ中)';
  if(msg) tpMsg('PLATEAU: 未取得 ' + msg);
}
// 12秒経っても来なければダミービルで遊べるようにする
setTimeout(()=>ensureFallback('(フォールバック街でプレイ中)'), 12000);

function buildFallbackCity(){
  const mat = facadeMat();
  for(let i=0;i<120;i++){
    const w=15+Math.random()*25, h=20+Math.random()*80, d=15+Math.random()*25;
    const m = new THREE.Mesh(new THREE.BoxGeometry(w,h,d), mat);
    const along=(i-60)*45, side=(Math.random()<.5?-1:1)*(60+Math.random()*120);
    // 四条通に沿って配置 (ECEF近似: 東西・南北ベクトルでオフセット)
    const east=new THREE.Vector3().crossVectors(new THREE.Vector3(0,0,1),UP).normalize();
    const north=new THREE.Vector3().crossVectors(UP,east).normalize();
    m.position.copy(ORIGIN).addScaledVector(east,side).addScaledVector(north,along).addScaledVector(UP,h/2);
    m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),UP);
    scene.add(m);
  }
}

// ===== 1b. 夜景ドレスアップ =====
const eastA=new THREE.Vector3().crossVectors(new THREE.Vector3(0,0,1),UP).normalize();
const northA=new THREE.Vector3().crossVectors(UP,eastA).normalize();
let night=true;

let _facMat=null;
function facadeMat(){
  if(_facMat) return _facMat;
  const c=document.createElement('canvas'); c.width=128; c.height=256;
  const x=c.getContext('2d');
  x.fillStyle='#1b1f27'; x.fillRect(0,0,128,256);
  for(let iy=0;iy<14;iy++)for(let ix=0;ix<6;ix++){
    const lit=Math.random()<0.45;
    x.fillStyle=lit?(Math.random()<0.7?'#ffd27a':'#bfe3ff'):'#0e1118';
    x.fillRect(6+ix*20,8+iy*17,12,10);
  }
  const tex=new THREE.CanvasTexture(c); tex.colorSpace=THREE.SRGBColorSpace;
  _facMat=new THREE.MeshStandardMaterial({map:tex,emissiveMap:tex,emissive:0xffc98a,emissiveIntensity:0.6,roughness:.9});
  return _facMat;
}

// 星・月
const starGeo=new THREE.BufferGeometry();
{ const n=700, arr=new Float32Array(n*3), v=new THREE.Vector3();
  for(let i=0;i<n;i++){ v.randomDirection().multiplyScalar(60000).add(ORIGIN); arr[i*3]=v.x; arr[i*3+1]=v.y; arr[i*3+2]=v.z; }
  starGeo.setAttribute('position',new THREE.BufferAttribute(arr,3)); }
const stars=new THREE.Points(starGeo,new THREE.PointsMaterial({color:0xbcd0ff,size:1.6,sizeAttenuation:false,fog:false,transparent:true,opacity:.9}));
stars.frustumCulled=false; scene.add(stars);
const moon=new THREE.Mesh(new THREE.CircleGeometry(1500,32),new THREE.MeshBasicMaterial({color:0xdfe8ff,fog:false}));
moon.position.copy(ORIGIN).addScaledVector(eastA,35000).addScaledVector(UP,22000);
moon.lookAt(ORIGIN); scene.add(moon);

// ネオン看板 (四条通沿い)
function neonTex(text,color){
  const c=document.createElement('canvas'); c.width=256; c.height=512;
  const x=c.getContext('2d');
  x.fillStyle='#07070f'; x.fillRect(0,0,256,512);
  x.strokeStyle=color; x.lineWidth=6; x.shadowColor=color; x.shadowBlur=25;
  x.strokeRect(14,14,228,484);
  x.fillStyle='#fff'; x.font='bold 84px sans-serif'; x.textAlign='center'; x.textBaseline='middle';
  const chs=[...text], n=chs.length;
  chs.forEach((ch,i)=>x.fillText(ch,128,n>1?90+340*i/(n-1):256));
  const t=new THREE.CanvasTexture(c); t.colorSpace=THREE.SRGBColorSpace; return t;
}
const NEON=[['KYOTO','#ff2fb3'],['四条','#22e6ff'],['ラーメン','#ffb02e'],['HOTEL','#ff4040'],['カラオケ','#7cff4f'],['京都','#ff2fb3'],['SPIDER','#22e6ff'],['ネオン','#ffb02e']];
const poleM=new THREE.MeshStandardMaterial({color:0x14161c,roughness:.8});
NEON.forEach((e,i)=>{
  const s=i%2?1:-1, along=-560+i*160;
  const m=new THREE.Mesh(new THREE.PlaneGeometry(9,18),
    new THREE.MeshBasicMaterial({map:neonTex(e[0],e[1]),side:THREE.DoubleSide,toneMapped:false}));
  m.position.copy(ORIGIN).addScaledVector(eastA,s*22).addScaledVector(northA,along).addScaledVector(UP,20);
  m.up.copy(UP); m.lookAt(m.position.clone().addScaledVector(eastA,-s));
  scene.add(m);
  const pole=new THREE.Mesh(new THREE.CylinderGeometry(0.3,0.3,20,6),poleM);
  pole.position.copy(m.position).addScaledVector(UP,-14);
  pole.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),UP);
  scene.add(pole);
});

