function buildFallbackCity(){
  const mat=facadeMat();
  const box=new THREE.BoxGeometry(1,1,1);
  const im=new THREE.InstancedMesh(box,mat,LITE?70:120);
  const east=new THREE.Vector3().crossVectors(new THREE.Vector3(0,0,1),UP).normalize();
  const north=new THREE.Vector3().crossVectors(UP,east).normalize();
  const mtx=new THREE.Matrix4(), q=new THREE.Quaternion(), scl=new THREE.Vector3(), pos=new THREE.Vector3();
  for(let i=0;i<im.count;i++){
    const w=15+Math.random()*25, h=20+Math.random()*80, d=15+Math.random()*25;
    const along=(i-im.count/2)*45, side=(Math.random()<0.5?-1:1)*(60+Math.random()*120);
    pos.copy(ORIGIN).addScaledVector(east,side).addScaledVector(north,along).addScaledVector(UP,h/2);
    scl.set(w,h,d);
    mtx.compose(pos,q,scl);
    im.setMatrixAt(i,mtx);
  }
  im.instanceMatrix.needsUpdate=true;
  scene.add(im);
}

