  if(keys['KeyW']&&!P.attached) P.vel.addScaledVector(fwd,60*dt);
  if(keys['KeyS']&&!P.attached) P.vel.addScaledVector(fwd,-10*dt);
  if(keys['KeyA']) P.vel.addScaledVector(right,-40*dt);
  if(keys['KeyD']) P.vel.addScaledVector(right,40*dt);
  if(!P.attached && fwd.dot(UP) < -0.25) P.vel.addScaledVector(fwd,(keys['KeyW']?90:20)*dt); // ダイブ加速
