    if(P.attached) P.ropeLen=Math.max(10,P.ropeLen-30*dt);
    else { holdTimer-=dt; if(holdTimer<=0){ holdTimer=0.15; shoot(); } }
  }
  autoTimer-=dt;
  if(autoMode && !P.attached && !holdReel && hAbove>8 && sp>4 && autoTimer<=0){ autoTimer=0.4; autoShoot(fwd); }

  if(P.attached){
