      P.pos.copy(P.anchor).addScaledVector(n,P.ropeLen);
      const vOut=P.vel.dot(n);
      if(vOut>0) P.vel.addScaledVector(n,-vOut);
      P.vel.addScaledVector(fwd,22*dt); // ポンプ加速
    }
    if(P.pos.distanceTo(P.anchor)>MAX_ROPE*1.2) detach(1);
  }
  if(hAbove<MIN_H){ P.pos.addScaledVector(UP,MIN_H-hAbove);
